function forcedFields(site,area){const ok=[];for(let k=0;k<8;k++){const b=k*45*R;let good=0;for(const d of [450,650,850]){const x=site.x+Math.sin(b)*d,z=site.z-Math.cos(b)*d,sf=surfaceProfile(x,z,area);if(['field','stubble','grass','dirt'].includes(sf.kind)&&sf.slope<.12&&obstacleClearance(x,z,area,30,2)>18)good++;}if(good>=2)ok.push(k);}
 if(!ok.length)return 'YAKINDA UYGUN SAHA AZ; PATERN AÇIK ARAZİ ÜZERİNDEN';return ok.slice(0,3).map(k=>DIRS_DA[k]).join(', ')+' AÇIK TARLALAR';}
