/* power lines: conductors up to ~20 m over the ground; the nearest span (index) within r metres, or null */
function wireNear(x,z,area,r=45){for(const [li,line] of (POWER_LINES[area]??[]).entries())for(let i=1;i<line.length;i++){const [ax,az]=line[i-1],[bx,bz]=line[i],dx=bx-ax,dz=bz-az,L=Math.hypot(dx,dz),u=Math.max(0,Math.min(L,((x-ax)*dx+(z-az)*dz)/L));if(Math.hypot(x-ax-dx/L*u,z-az-dz/L*u)<r)return li*100+i;}return null;}
